    #include <bits/stdc++.h>     using namespace std;     #define endl '\n'     using ll = long long;      void solve() {         int n;         cin >> n;         vector<int>a(n);         for(int &i : a) cin >> i;          int ans = n, i1 = 0, i2 = 0;         int first = a[0];          for(int i = 0; i < n; i++) {             if(a[0] == a[i]) {                 i1++;             } else                  break;         }          for(int i = n - 1; i >= 0; i--) {             if(a[i] == a[n-1]) {                 i2++;             } else                  break;          }           if(a[0] == a[n-1]){             ans -= i1;             ans -= i2;         } else {             ans -= max({i1,i2});         }           // cout << i1 << ' ' << i2 << ' '<< i3 << endl;         cout << max(0,ans)  << endl;     }      int main() {         ios::sync_with_stdio(false);         cin.tie(0); cout.tie(0);          int t;         cin >> t;         while (t--) {             solve();         }         return 0;     }
